import { describe, it, expect, beforeEach, vi } from 'vitest';
import { useEffect, useState } from 'react';
import { render, waitFor } from '@testing-library/react';
import type { BacklogItem } from '@/lib/deferred-backlog';

/**
 * specs/0083 W2b — the meeting page never starts a recording's summary.
 *
 * The Rust wrap-up starts it (in parallel with diarization) whether or not the window is
 * awake. A page that also auto-generated on `?source=recording` would be a second summary of
 * the same meeting. An audio import (`?source=import`) keeps today's page-driven path.
 *
 * These exercise the PAGE: the props it hands PageContent and the commands it runs.
 */

const {
  invoke, toastInfo, paginated, loadingPaginated, sidebar, router, searchParams, deepLink,
} = vi.hoisted(() => {
  // Stable identities: the page syncs metadata+transcripts into state in an effect, so a
  // fresh object per render would loop ("Maximum update depth exceeded") in jsdom.
  const segments = [{ id: 's1', text: 'hello' }];
  return {
    invoke: vi.fn(),
    toastInfo: vi.fn(),
    paginated: {
      metadata: {
        id: 'm-1',
        title: 'Standup',
        created_at: '2026-08-14T10:00:00Z',
        updated_at: '2026-08-14T10:30:00Z',
        folder_path: '/rec/m-1',
      },
      segments,
      transcripts: segments,
      isLoading: false,
      isLoadingMore: false,
      hasMore: false,
      totalCount: 1,
      loadedCount: 1,
      loadMore: vi.fn(),
      refetch: vi.fn(),
      error: null,
    },
    sidebar: {
      setCurrentMeeting: vi.fn(),
      refetchMeetings: vi.fn(),
      stopSummaryPolling: vi.fn(),
      isMeetingActive: false,
      activeRecordingMeetingId: null,
    },
    router: { push: vi.fn(), replace: vi.fn() },
    searchParams: { current: new URLSearchParams('id=m-1&source=recording') },
    deepLink: { pendingSegmentId: null, consume: vi.fn() },
    loadingPaginated: {
      metadata: null,
      segments: [],
      transcripts: [],
      isLoading: true,
      isLoadingMore: false,
      hasMore: false,
      totalCount: 0,
      loadedCount: 0,
      loadMore: vi.fn(),
      refetch: vi.fn(),
      error: null,
    },
  };
});

let backlogItems: BacklogItem[] = [];

vi.mock('@tauri-apps/api/core', () => ({ invoke }));
vi.mock('sonner', () => ({
  toast: { info: toastInfo, success: vi.fn(), warning: vi.fn(), error: vi.fn() },
}));
vi.mock('next/navigation', () => ({
  useSearchParams: () => searchParams.current,
  useRouter: () => router,
}));
vi.mock('@/contexts/DeferredBacklogProvider', () => ({
  useBacklog: () => ({
    view: {
      items: backlogItems,
      pendingCount: backlogItems.length,
      processing: backlogItems.length > 0,
      active: backlogItems[0] ?? null,
      activeOrdinal: backlogItems.length ? 1 : 0,
      total: backlogItems.length,
    },
    enqueueMeeting: vi.fn(),
    stop: vi.fn(),
    dismissDone: vi.fn(),
    startNow: vi.fn(),
  }),
}));
vi.mock('@/components/Sidebar/SidebarProvider', () => ({
  useSidebar: () => sidebar,
}));
vi.mock('@/contexts/ConfigContext', () => ({
  useConfig: () => ({ isAutoSummary: true }),
}));
vi.mock('@/contexts/RecordingStateContext', () => ({
  useRecordingState: () => ({ isRecording: false }),
}));
// Mirrors the real hook's timing: metadata/transcripts land a render AFTER mount, which
// is what lets the page's mount-time reset effects run before the metadata sync effect.
vi.mock('@/hooks/usePaginatedTranscripts', () => ({
  usePaginatedTranscripts: () => {
    const [loaded, setLoaded] = useState(false);
    useEffect(() => {
      setLoaded(true);
    }, []);
    return loaded ? paginated : loadingPaginated;
  },
}));
vi.mock('@/hooks/useSegmentDeepLink', () => ({
  useSegmentDeepLink: () => deepLink,
}));
const pageContentProps: Array<{ shouldAutoGenerate: boolean }> = [];
vi.mock('../page-content', () => ({
  default: (props: { shouldAutoGenerate: boolean }) => {
    pageContentProps.push(props);
    return <div data-testid="page-content" />;
  },
}));

import MeetingDetails from '../page';

beforeEach(() => {
  vi.clearAllMocks();
  backlogItems = [];
  pageContentProps.length = 0;
  invoke.mockImplementation(async (cmd: string) => {
    switch (cmd) {
      case 'api_get_summary':
        return { status: 'idle', data: null };
      case 'api_get_model_config':
        return { provider: 'ollama', model: 'llama3' };
      default:
        return null;
    }
  });
});

const settle = () => new Promise((resolve) => setTimeout(resolve, 0));
const autoGenerated = () => pageContentProps.some((p) => p.shouldAutoGenerate);

describe('meeting-details auto-summary gate (specs/0083)', () => {
  it('never auto-generates for source=recording — the wrap-up already started it', async () => {
    searchParams.current = new URLSearchParams('id=m-1&source=recording');
    render(<MeetingDetails />);

    await waitFor(() => expect(pageContentProps.length).toBeGreaterThan(0));
    await settle();
    expect(autoGenerated()).toBe(false);
    // Not even the probes that only a recording ever needed.
    expect(invoke).not.toHaveBeenCalledWith('api_get_model_config');
    expect(invoke).not.toHaveBeenCalledWith('api_get_meeting_processing_mode', expect.anything());
    expect(toastInfo).not.toHaveBeenCalled();
  });

  it('still auto-generates for an audio import (source=import)', async () => {
    searchParams.current = new URLSearchParams('id=m-1&source=import');
    render(<MeetingDetails />);

    await waitFor(() => expect(autoGenerated()).toBe(true));
  });
});
